using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
using TasiaCraft;
public static class ProjectSaveTest {
 static string root,log;static int passed;static readonly BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;static readonly JavaScriptSerializer json=new JavaScriptSerializer();
 sealed class CodedIOException:IOException {public CodedIOException(int win32){HResult=unchecked((int)(0x80070000u|(uint)win32));}}
 static void Require(bool ok,string label){if(!ok)throw new Exception(label);passed++;File.AppendAllText(log,"PASS "+label+Environment.NewLine);}
 static object Field(Editor editor,string name){return typeof(Editor).GetField(name,flags).GetValue(editor);}
 static void Set(Editor editor,string name,object value){typeof(Editor).GetField(name,flags).SetValue(editor,value);}
 static Exception Failure(Action action){try{action();}catch(Exception ex){if(ex is TargetInvocationException)return ex.InnerException;return ex;}throw new Exception("Expected save failure");}
 static void Clean(string path,string label){Require(Directory.GetFiles(Path.GetDirectoryName(path),Path.GetFileName(path)+".*.tmp").Length==0,label+" temp file cleanup");}
 static void SameFile(string path,byte[] bytes,string label){Require(File.ReadAllBytes(path).SequenceEqual(bytes),label);}
 static void Fixture(string path){using(var image=new System.Drawing.Bitmap(320,180)){using(var g=System.Drawing.Graphics.FromImage(image)){g.Clear(System.Drawing.Color.Red);g.FillRectangle(System.Drawing.Brushes.Blue,160,0,160,180);}image.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
 static void Reopen(Project expected,string path,string label){var actual=Engine.Load(path);Require(json.Serialize(actual)==json.Serialize(expected),label+" all project fields roundtrip");}
 static void Export(Project p){string video=Path.Combine(root,"recovered.mp4"),png=Path.Combine(root,"recovered.png");Engine.Render(p,video,null);Engine.Run("ffmpeg","-y -v error -ss 0.2 -i "+Engine.Quote(video)+" -frames:v 1 -threads 1 "+Engine.Quote(png));using(var image=new System.Drawing.Bitmap(png)){Require(image.Width==320&&image.Height==180,"recovered saved project exports correct dimensions");var red=image.GetPixel(80,90);var blue=image.GetPixel(240,90);Require(red.R>180&&red.B<70,"recovered saved project exports retained red pixels");Require(blue.B>180&&blue.R<70,"recovered saved project exports retained blue pixels");}}
 [STAThread]public static void Main(string[] args){root=args[0];Directory.CreateDirectory(root);log=Path.Combine(root,"results.txt");File.WriteAllText(log,"");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var editor=new Editor();string recent=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TasiaCraft","recents.json");byte[] recentBefore=File.Exists(recent)?File.ReadAllBytes(recent):null;
  editor.Loaded+=(s,e)=>{try{
   typeof(Editor).GetMethod("HideHome",flags).Invoke(editor,null);string source=Path.Combine(root,"source.png");Fixture(source);byte[] sourceBytes=File.ReadAllBytes(source);var media=Engine.Probe(source);var project=new Project{Width=320,Height=180,TrackCount=3};project.Media.Add(media);project.Clips.Add(new Clip{MediaId=media.Id,NativeSize=true,Duration=1,CropLeft=.125,CropRight=.125});project.LockedTracks.Add(2);project.SnapDisabledTracks.Add(1);string destination=Path.Combine(root,"復元された проект.tasiaproj");Engine.Save(project,destination);Reopen(project,destination,"new unicode save");Clean(destination,"new save");project.Clips[0].Volume=.75;Engine.Save(project,destination);Reopen(project,destination,"unlocked replacement");Clean(destination,"replacement");
   byte[] prior=File.ReadAllBytes(destination);project.Clips[0].X=10;string state=json.Serialize(project);var watch=Stopwatch.StartNew();using(var held=new FileStream(destination,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){
    var release=Task.Run(()=>{Thread.Sleep(300);held.Dispose();});Engine.Save(project,destination);release.Wait();
   }watch.Stop();Require(watch.ElapsedMilliseconds>=200&&watch.ElapsedMilliseconds<6000,"temporary no-delete lock recovers automatically in bounded time ("+watch.ElapsedMilliseconds+"ms)");Require(json.Serialize(project)==state,"successful retry does not mutate project");Reopen(project,destination,"recovered replacement");Clean(destination,"recovered save");Require(!File.ReadAllBytes(destination).SequenceEqual(prior),"recovered replacement contains updated state");Export(Engine.Load(destination));
   prior=File.ReadAllBytes(destination);project.Clips[0].X=20;state=json.Serialize(project);Exception error;watch.Restart();using(var held=new FileStream(destination,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){error=Failure(()=>Engine.Save(project,destination));}watch.Stop();Require(error is IOException,"persistent sharing lock reports IO failure");Require(error.HResult==unchecked((int)0x80070020),"real no-delete lock yields sharing violation32 (not synthetic1175)");Require(watch.ElapsedMilliseconds>=1000&&watch.ElapsedMilliseconds<6000,"persistent sharing lock fails within bounded retry window ("+watch.ElapsedMilliseconds+"ms)");SameFile(destination,prior,"persistent lock preserves previous project bytes");Require(json.Serialize(project)==state,"persistent lock preserves in-memory project");Clean(destination,"persistent lock failure");
   string missing=Path.Combine(root,"missing-"+Guid.NewGuid().ToString("N"),"save.tasiaproj");watch.Restart();error=Failure(()=>Engine.Save(project,missing));watch.Stop();Require(error is DirectoryNotFoundException,"missing directory reports precise failure");Require(watch.ElapsedMilliseconds<1000,"missing directory failure is immediate");Require(!Directory.Exists(Path.GetDirectoryName(missing)),"missing directory save does not create directories");
   File.SetAttributes(destination,File.GetAttributes(destination)|FileAttributes.ReadOnly);try{watch.Restart();error=Failure(()=>Engine.Save(project,destination));watch.Stop();Require(error is UnauthorizedAccessException||error is IOException,"read-only destination rejected");Require(watch.ElapsedMilliseconds<1000,"read-only destination failure is immediate");SameFile(destination,prior,"read-only destination preserves bytes");Clean(destination,"read-only failure");}finally{File.SetAttributes(destination,FileAttributes.Normal);}
   project.Clips[0].Duration=double.NaN;error=Failure(()=>Engine.Save(project,destination));Require(error is InvalidDataException,"invalid project rejected");SameFile(destination,prior,"invalid project preserves prior bytes");Clean(destination,"invalid project failure");project.Clips[0].Duration=1;error=Failure(()=>Engine.Save(project,source));Require(error is InvalidDataException,"source-media destination rejected");SameFile(source,sourceBytes,"source media bytes preserved");Clean(source,"source-media protection");
   var classify=typeof(Engine).GetMethod("IsTransientSaveError",BindingFlags.Static|BindingFlags.NonPublic);Require(classify!=null,"transient save classifier available");foreach(int code in new[]{32,33,1175})Require((bool)classify.Invoke(null,new object[]{new CodedIOException(code)}),"classifier accepts Windows code "+code);foreach(int code in new[]{2,3,5,31,34,112,1174,1176})Require(!(bool)classify.Invoke(null,new object[]{new CodedIOException(code)}),"classifier rejects Windows code "+code);
   Set(editor,"project",project);Set(editor,"projectPath",destination);Set(editor,"dirty",true);editor.Title=ProductInfo.DisplayName+" — "+Path.GetFileName(destination)+" *";string oldTitle=editor.Title;((TextBlock)Field(editor,"title")).Text="Original title label";((TextBlock)Field(editor,"status")).Text="Unsaved editing status";var saveMethod=typeof(Editor).GetMethod("SaveProjectTo",flags);Require(saveMethod!=null,"editor transactional save entry point available");error=Failure(()=>saveMethod.Invoke(editor,new object[]{missing}));Require(error is DirectoryNotFoundException,"failed Save As propagates save error");Require((string)Field(editor,"projectPath")==destination,"failed Save As preserves original destination path");Require((bool)Field(editor,"dirty"),"failed Save As keeps dirty state");Require(editor.Title==oldTitle,"failed Save As preserves versioned window title");Require(((TextBlock)Field(editor,"title")).Text=="Original title label","failed Save As preserves title label");Require(((TextBlock)Field(editor,"status")).Text=="Unsaved editing status","failed Save As preserves status");if(recentBefore!=null)SameFile(recent,recentBefore,"failed Save As preserves recents");else Require(!File.Exists(recent),"failed Save As creates no recents");
   string asNew=Path.Combine(root,"成功 new project.tasiaproj");saveMethod.Invoke(editor,new object[]{asNew});Require((string)Field(editor,"projectPath")==asNew,"successful Save As commits new destination");Require(!(bool)Field(editor,"dirty"),"successful Save As clears dirty state");Require(editor.Title==ProductInfo.DisplayName+" — "+Path.GetFileName(asNew),"successful Save As commits versioned window title");Require(((TextBlock)Field(editor,"title")).Text==Path.GetFileNameWithoutExtension(asNew),"successful Save As commits title label");Require(((TextBlock)Field(editor,"status")).Text=="Project saved","successful Save As commits saved status");Reopen(project,asNew,"successful editor Save As");SameFile(destination,prior,"Save As preserves previous project file");Clean(asNew,"editor save");SameFile(source,sourceBytes,"all save paths preserve source media");
   File.AppendAllText(log,"PASS total "+passed+Environment.NewLine);app.Shutdown(0);
  }catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);Set(editor,"dirty",false);app.Shutdown(1);}finally{if(recentBefore!=null){Directory.CreateDirectory(Path.GetDirectoryName(recent));File.WriteAllBytes(recent,recentBefore);}else if(File.Exists(recent))File.Delete(recent);Set(editor,"dirty",false);var live=Field(editor,"live") as LivePreview;if(live!=null)live.Dispose();}};app.Run(editor);
 }
}


